// Horizontal mode only, so that every run-length code of T.4 is used, of both
// colors: each pair of rows has a white run of `r` before one black pixel, and
// a black run of `r` after one white pixel, for `r` of 0 to 63 and 64 to 2560 by
// 64. `ccittfax4_decode` returns the image below.
const ALL_CODES =
  "";
const ALL_CODES_WIDTH = 3000;

// Two rows of 5300 pixels, whose runs of 5200 and 5197 take two makeup codes.
const LONG_RUNS = "ID4D+6gPDUMAPgPgeCHYqG4AIAI=";

test("decodes the streams imagecodecs decodes", async () => {
  for (const { height, width, encoded, expected } of [
    ...LIBTIFF_CASES,
    ...ENCODER_CASES,
  ]) {
    const bytes = fromBase64(expected);
    expect(decodeCcittGroup4(fromBase64(encoded), height, width)).toEqual(
      bytes,
    );
    // With leading dimensions of 1, through the codec chain.
    expect(
      await decodeArray(
        parseCodecChainSpec([{ name: "imagecodecs_ccittfax4" }], {
          dataType: DataType.UINT8,
          chunkShape: [1, 1, height, width],
        }),
        fromBase64(encoded),
        new AbortController().signal,
      ),
    ).toEqual(bytes);
  }
});

test("decodes every run-length code", () => {
  const runs: number[] = [];
  for (let r = 0; r < 64; ++r) runs.push(r);
  for (let r = 64; r <= 2560; r += 64) runs.push(r);
  const height = runs.length * 2;
  const expected = new Uint8Array(height * ALL_CODES_WIDTH);
  runs.forEach((r, i) => {
    const white = 2 * i * ALL_CODES_WIDTH;
    expected[white + r] = 1;
    const black = (2 * i + 1) * ALL_CODES_WIDTH;
    expected.fill(1, black + 1, black + 1 + r);
  });
  // Not `toEqual`, which takes seconds over half a million elements.
  const decoded = decodeCcittGroup4(
    fromBase64(ALL_CODES),
    height,
    ALL_CODES_WIDTH,
  );
  expect(decoded.length).toBe(expected.length);
  expect(decoded.findIndex((value, i) => value !== expected[i])).toBe(-1);
});

test("decodes a run of more than one makeup code", () => {
  const expected = new Uint8Array(2 * 5300);
  expected.fill(1, 5200, 5300);
  expected.fill(1, 5300 + 3, 5300 + 5200);
  expect(decodeCcittGroup4(fromBase64(LONG_RUNS), 2, 5300)).toEqual(expected);
});

test("rejects other data types", () => {
  expect(() =>
    parseCodecChainSpec([{ name: "imagecodecs_ccittfax4" }], {
      dataType: DataType.UINT16,
      chunkShape: [2, 2],
    }),
  ).toThrow(/supports the uint8 data type, not uint16/);
});

test("rejects a chunk of more than one image", () => {
  expect(() =>
    parseCodecChainSpec([{ name: "imagecodecs_ccittfax4" }], {
      dataType: DataType.UINT8,
      chunkShape: [2, 3, 4],
    }),
  ).toThrow(/all but its last two dimensions must be 1/);
});

test("rejects a chunk of less than two dimensions", () => {
  expect(() =>
    parseCodecChainSpec([{ name: "imagecodecs_ccittfax4" }], {
      dataType: DataType.UINT8,
      chunkShape: [4],
    }),
  ).toThrow(/all but its last two dimensions must be 1/);
});

test("rejects a stream that ends before the image", () => {
  // One V0 code a row: the byte holds 8 rows of the 9.
  expect(() => decodeCcittGroup4(Uint8Array.of(0xff), 9, 4)).toThrow(
    /the stream ends at row 8 of an image of 9 rows/,
  );
});

test("rejects an end-of-facsimile-block code before the last row", () => {
  // V0, then 000000000001 000000000001.
  expect(() =>
    decodeCcittGroup4(Uint8Array.of(0x80, 0x08, 0x00, 0x80), 2, 4),
  ).toThrow(/the stream ends at row 1 of an image of 2 rows/);
});

test("rejects a code cut off by the end of the stream", () => {
  // 001, a horizontal code, then the 8-bit white code 00110101 cut off after 5
  // bits, which with the 0s after the stream reads as the 7-bit code of 28.
  expect(() => decodeCcittGroup4(Uint8Array.of(0x26), 1, 4)).toThrow(
    /ends before the image does/,
  );
});

test("rejects an extension code", () => {
  // 0000001 111, the uncompressed mode of T.6.
  expect(() => decodeCcittGroup4(Uint8Array.of(0x03, 0xc0), 1, 4)).toThrow(
    /unsupported or invalid mode code at bit 0/,
  );
});

test("rejects an invalid run code", () => {
  // 001, a horizontal code, then 13 zeros, which no white run code starts with.
  expect(() =>
    decodeCcittGroup4(Uint8Array.of(0x20, 0x00, 0x00), 1, 4),
  ).toThrow(/invalid white run code at bit 3/);
});

test("rejects a run past the end of the row", () => {
  // 001, a horizontal code, then 1000, a white run of 3, and 10, a black run of
  // 3, in a row of 4.
  expect(() => decodeCcittGroup4(Uint8Array.of(0x31, 0x00), 1, 4)).toThrow(
    /row 0 changes color at 6, after reaching 3 of a width of 4/,
  );
});

test("rejects a code left of the start of the row", () => {
  // 0000010, VL3, against a b1 at the width of 1.
  expect(() => decodeCcittGroup4(Uint8Array.of(0x04), 1, 1)).toThrow(
    /row 0 changes color at -2, after reaching -1 of a width of 1/,
  );
});

test("rejects a code that does not move right", () => {
  // 010 010, VL1 twice, against a b1 at the width of 2: both changes are at 1.
  expect(() => decodeCcittGroup4(Uint8Array.of(0x48), 1, 2)).toThrow(
    /row 0 changes color at 1, after reaching 1 of a width of 2/,
  );
});

test("rejects an empty run where a row goes on", () => {
  // 001, a horizontal code, then 1000, a white run of 3, and 0000110111, a black
  // run of 0, in a row of 4.
  expect(() =>
    decodeCcittGroup4(Uint8Array.of(0x30, 0x1b, 0x80), 1, 4),
  ).toThrow(/row 0 changes color at 3, after reaching 3 of a width of 4/);
});
